class Solution:
    def combinationSum3(self, k: int, n: int) -> list[list[int]]:
        result = []

        def backtrack(start: int, remaining: int, current: list[int]) -> None:
            if len(current) == k:
                if remaining == 0:
                    result.append(current[:])
                return
            for i in range(start, 10):
                if i > remaining:
                    break
                current.append(i)
                backtrack(i + 1, remaining - i, current)
                current.pop()

        backtrack(1, n, [])
        return result

